namespace WinUp {
    static class DesktopQaProgram {
        [STAThread] static void Main() {
            try {File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"qa-start.txt"),"started");Run();}
            catch(Exception ex){File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"qa-results.json"),new JavaScriptSerializer().Serialize(new[]{new{name="Startup",passed=false,error=ex.ToString()}}));}
        }
        static void Run() {
            DesktopDependencies.Ensure();
            ComponentResources.Initialize();
            AppDomain.CurrentDomain.AssemblyResolve+=(s,e)=>new AssemblyName(e.Name).Name=="KeePassLib"?CoreLoader.Resolve():EmbeddedModules.Resolve(e.Name);
            Directory.CreateDirectory(Paths.Data);Directory.CreateDirectory(Paths.Apps);CoreLoader.EnsureDir();
            Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);
            Application.SetUnhandledExceptionMode(UnhandledExceptionMode.CatchException);
            Application.ThreadException+=(s,e)=>{File.WriteAllText(Path.Combine(Paths.Root,"qa-thread-error.txt"),e.Exception.ToString());Application.Exit();};
            var store=AppStore.Load();store.Settings.WizardDone=true;store.Settings.HideFromCapture=false;store.Settings.AutoLockMinutes=1440;store.Settings.BackupDir=Path.Combine(Paths.Root,"backups");store.Save();
            var form=new MainForm(store,false);
            form.Shown+=async(s,e)=>await form.DesktopQa();
            Application.Run(form);
        }
    }
