        void QaProbeRegression(){
            var uri=new Uri("https://example.invalid/path/login");var calls=new List<string>();
            string result=PublicWebProbe.CheckHttp(uri,method=>{calls.Add(method);return new PublicWebProbe.HttpStatus{Code=method=="HEAD"?405:200};});
            QaCheck("HEAD refusal retries GET once and identifies fallback",calls.SequenceEqual(new[]{"HEAD","GET"})&&result.Contains("HTTP 200")&&result.Contains("GET вместо HEAD"));
            calls.Clear();result=PublicWebProbe.CheckHttp(uri,method=>{calls.Add(method);return new PublicWebProbe.HttpStatus{Code=302,Location="/login"};});QaCheck("Relative redirect is resolved and is never followed",calls.Count==1&&result.Contains("https://example.invalid/login"));
            QaCheck("Cross-domain and unsafe redirects have distinct results",PublicWebProbe.Describe(uri,new PublicWebProbe.HttpStatus{Code=302,Location="https://other.invalid/login"},"HEAD").Contains("другой домен")&&PublicWebProbe.Describe(uri,new PublicWebProbe.HttpStatus{Code=302,Location="http://example.invalid/login"},"HEAD").Contains("без HTTPS")&&PublicWebProbe.Describe(uri,new PublicWebProbe.HttpStatus{Code=302,Location="https://127.0.0.1/login"},"HEAD").Contains("внутренний"));
            QaCheck("Missing page, rate limit and server failure are distinguished",PublicWebProbe.Describe(uri,new PublicWebProbe.HttpStatus{Code=404},"HEAD").Contains("не найдена")&&PublicWebProbe.Describe(uri,new PublicWebProbe.HttpStatus{Code=429},"HEAD").Contains("много запросов")&&PublicWebProbe.Describe(uri,new PublicWebProbe.HttpStatus{Code=503},"HEAD").Contains("ошибка сервера"));
            using(var bytes=new MemoryStream(System.Text.Encoding.ASCII.GetBytes("HTTP/1.1 103 Early Hints\r\nLink: </style.css>\r\n\r\nHTTP/1.1 200 OK\r\nContent-Length: 500000000\r\n\r\n"))){QaCheck("HTTP parser skips interim headers without reading page body",PublicWebProbe.ReadResponse(bytes,System.Diagnostics.Stopwatch.StartNew()).Code==200&&bytes.Position==bytes.Length);}
            bool rejected=false;try{using(var bytes=new MemoryStream(System.Text.Encoding.ASCII.GetBytes("HTTP/1.1 200 OK\r\nX-Test: "+new string('x',33000)+"\r\n\r\n")))PublicWebProbe.ReadResponse(bytes,System.Diagnostics.Stopwatch.StartNew());}catch(IOException){rejected=true;}QaCheck("Oversized HTTP headers are rejected",rejected);
            QaCheck("Private destinations and URL credentials stay blocked",PublicWebProbe.Check("https://127.0.0.1",System.Threading.CancellationToken.None).Contains("Внутренний")&&PublicWebProbe.Check("https://name:secret@example.invalid",System.Threading.CancellationToken.None).Contains("без данных входа"));
            var profile=LoginProfiles.All.First(p=>p.Sites.Length>0&&p.LoginUrl!=p.Sites[0]&&p.Mode=="form");
            var row=AccountAddressReview.Inspect(new LoginEntry{Id="qa-login-path",Name=profile.Id,LoginProfile=profile.Id,Target=profile.Sites[0],LoginUrl=profile.Sites[0]},new LocalApplication[0]);
            QaCheck("Home-page login address proposes reviewed service route",row.FixLogin&&row.LoginUrl==profile.LoginUrl&&row.LoginHint.Contains(profile.Id));
            var custom=AccountAddressReview.Inspect(new LoginEntry{Id="qa-custom-path",Name=profile.Id,LoginProfile=profile.Id,Target=profile.Sites[0],LoginUrl=profile.Sites[0]+"/my-custom-login"},new LocalApplication[0]);QaCheck("Custom login route is retained",!custom.FixLogin);
        }
